INSERT INTO cidafm_commands ("id", "type", "name", "description", "default_active", "is_builtin", "created_at", "updated_at") VALUES
  ('842e1239-f1eb-4226-b912-5cce37795f46', '!', 'import-cid', 'Read a CID and process its contents. If a [Context] section is present, add its contents to current chat memory. If an [AFMs] section is present, store the AFMs without activating them.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('95d887ff-1bc7-4516-8d28-b30f72a317f8', '!', 'export-context', 'Summarize the current chat memory in preparation for transfer to a new chat. Returns a detailed, cold-start compatible summary under a [Context] tag.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('4e9797e9-6c06-4f4d-b460-2a8492bd9dda', '!', 'state-check', 'Create a list of all currently active state modifier AFMs and their current toggle status (on or off).', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('cce6654b-6bc0-48e8-b1b1-f4cb011e870a', '!', 'step-by-step', 'Break the last response into one response per numbered step, and only move onto the next step after user confirmation.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('4f11ad90-7428-4217-a9c7-0de0834c7290', '^', 'cidafm-optimize', 'Take the requested text and create a new version that is token-efficient, clear of redundancies, and context-independent. Then assess the newly generated text for meaningfulness retention, token efficiency, lack of redundancy, and context-independence.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('eb759e02-6eab-47ad-b4fd-638a76f76098', '^', 'fad', 'Assume the contents of the prompt are a proposition, then provide the best argument for it, followed by the best argument against it. Then, provide your decision based on both arguments.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('97ec5ee0-5c36-4302-a0c5-9aeabb12dce2', '^', 'concise', 'Make only the current response concise and to the point, minimizing word count while preserving meaning.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('c2ac26a4-5687-4e81-bcb9-51bd31197a18', '^', 'detailed', 'Provide a comprehensive and detailed response with thorough explanations and examples.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('88003187-d6c7-4195-a2c2-1f2afc083d69', '^', 'creative', 'Apply creative thinking and novel approaches to the response, encouraging innovative solutions.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('b858bb94-dc4e-4233-a820-78bf1b3c3110', '&', 'token-efficient', 'Minimize the number of tokens used in responses while preserving clarity and relevance. Automatically prioritize brevity and reduce redundancy without losing meaning.', TRUE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('3fbe7b95-df5f-48e2-8cc3-eb93098bfeff', '&', 'context-independent', 'Ensure responses are as context-independent as possible, providing all necessary information for complete understanding without relying on external context.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('16b6ccd9-d4bd-4a9c-82d2-ff1419804e56', '&', 'disciplined', 'Follow explicit user instructions without inference. Request clarification if instructions are unclear. Do not make assumptions about user intent.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('22259fff-26e0-4110-b1ed-0dbb0389ba4e', '&', 'friendly', 'Make all responses more warm and personable, using a conversational and approachable tone.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('f2dc22fb-7e0f-45f0-be06-4b66c6946c04', '&', 'professional', 'Maintain a formal, business-appropriate tone in all responses. Use professional language and structure.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('e5f43416-95d9-4642-9b27-68b42ad9fb1f', '&', 'technical', 'Focus on technical accuracy and precision. Include relevant technical details and use appropriate terminology.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('20776b1f-1b34-4f76-8a0f-d9d5ef172aa1', '&', 'educational', 'Structure responses to be educational, explaining concepts step-by-step and providing learning context.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('c4dc93de-b7b2-4f10-9369-b05578482c29', '!', 'cost-estimate', 'Calculate and display the estimated cost for the current conversation or proposed query.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('578bde3f-0ba4-401e-a487-09ec77f1d957', '!', 'model-info', 'Display information about the currently selected LLM model including capabilities, pricing, and optimal use cases.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('0b29f35c-3324-42e4-b038-110e671e924b', '!', 'usage-stats', 'Show current usage statistics including tokens consumed, costs, and performance metrics.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('f11904f2-d601-4d9a-a73b-b06a7eb114f6', '^', 'code-focused', 'Prioritize code examples and technical implementation details in the response.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('4663f585-123b-4809-9fbd-36e72bbeb1fb', '^', 'beginner-friendly', 'Explain concepts assuming no prior knowledge, using simple language and basic examples.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('d0a00e5f-34cf-4dcf-8c61-7ca1ad1da277', '^', 'bullet-points', 'Structure the response using bullet points and lists for easy scanning.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('2ee2f7ef-4548-4569-8bcd-a605017902a7', '^', 'with-examples', 'Include practical examples and use cases to illustrate all concepts discussed.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('3d90bea0-b8fb-4334-b3b5-30b34e57f6f2', '&', 'cost-conscious', 'Always consider and minimize token usage and costs. Provide cost warnings for expensive operations.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('cdf252d9-bdcd-45b6-892f-e1f54f5c643b', '&', 'security-focused', 'Prioritize security considerations and best practices in all responses.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('90562e91-e48d-4a3e-ae38-eff99464c5a9', '&', 'multilingual', 'Be prepared to respond in multiple languages and consider international perspectives.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00'),
  ('ed5d6ef7-f3c5-4d1a-91fc-47af433c0117', '&', 'accessible', 'Ensure responses are accessible to users with different abilities and technical backgrounds.', FALSE, TRUE, '2025-06-30T13:06:30.428525+00:00', '2025-06-30T13:06:30.428525+00:00');
