  ('3de4f7aa-00fd-4107-9aba-cbb36c8b306c', 'b99c36be-8dd0-4f24-9f12-f835f8dcb159', 'db94682e-5184-496f-93fd-dc739aa0f9e7', 'executeTask', 'Conduct market research on small business adoption of AI tools. What are the main barriers to adoption? What features do they value most?', '{}'::jsonb, NULL, '{}'::jsonb, 'pending', 0, 'Task created, waiting for execution...', '{}'::jsonb, '{}'::jsonb, NULL, NULL, NULL, NULL, NULL, 300, '{}'::jsonb, '2025-08-05T14:54:49.493374+00:00', '2025-08-05T14:54:49.701305+00:00', 'text', '{}'::jsonb),
